StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_SP_AutoSwitch                                                                                                                                                                                                                                                                 
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-06-04		William Veim			Initial release
//
//==============================================================================================================================
//
// 		FUNCTIONALITY:
// 		Trigger change of setpoint based on analog or digital trigger (including delay)
//
//==============================================================================================================================
 
 IF Inp_SetpointData.AutoSwitch_Active THEN
	 CASE Inp_SetpointData.AutoSwitch_TriggerType OF 
			
			0: //NOT IN USE
			
				Wrk_Trigger:=	FALSE;

			1: //CUSTOM
			
				Wrk_Trigger:=	Inp_CustomTrigger;
				
			2: //ANALOG VALUE OVER LIMIT
			
				Wrk_Trigger:= EXT_AnalogValue[Inp_SetpointData.AutoSwitch_AnalogIndex].EXT_Operator.ProcessValue >  Inp_SetpointData.AutoSwitch_Trig_AnaLimit;
			
			3: //ANALOG VALUE UNDER LIMIT
			
				Wrk_Trigger:= EXT_AnalogValue[Inp_SetpointData.AutoSwitch_AnalogIndex].EXT_Operator.ProcessValue < Inp_SetpointData.AutoSwitch_Trig_AnaLimit;
				
	 END_CASE;
 ELSE
	 Wrk_Trigger:=	FALSE;
 END_IF;
 
IF Inp_SetpointData.AutoSwitch_TriggerType = 1 THEN
 Inp_SetpointData.SetpointValue.Process_Desc:=Inp_CustomTrigger_Suffix;
END_IF;
 
TON_TrigActivate(In:=Wrk_Trigger, PT:=SecToTime(Inp_SetpointData.AutoSwitch_TrigDelay));

TON_TrigReturn(In:=NOT Wrk_Trigger, PT:=SecToTime(Inp_SetpointData.AutoSwitch_ReturnDelay));

//Auto Switch logic
IF TON_TrigActivate.Q THEN
	Wrk_AutoSwitch := TRUE;
ELSIF TON_TrigReturn.Q OR NOT Inp_SetpointData.AutoSwitch_Active THEN
	Wrk_AutoSwitch := FALSE;
END_IF;

Out_AutoSwitch:= Wrk_AutoSwitch;
Sts_AutoSwitch_InUse:= Inp_SetpointData.AutoSwitch_Active;
